import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';const{db}=await import('./reply-runtime-20261015.mjs');const dir='artifacts/realtor-batch-20261019';const ids=(await fs.readFile(dir+'/restored-fresh-reserves.jsonl','utf8')).trim().split('\n').map(JSON.parse).filter(x=>x.at>'2026-10-19T19:00:00Z').map(x=>x.id);const jobs=await db('sequence_jobs',{id:'in.('+ids.join(',')+')',select:'id,status,provider_sid,last_error'});const provider=jobs.map(x=>String(x.provider_sid||'').replace('telnyx:','')).filter(Boolean);const events=await db('crm_sms_provider_events',{provider_message_id:'in.('+provider.join(',')+')',event_type:'eq.message.finalized',order:'occurred_at.asc',select:'provider_message_id,status,occurred_at'});const latest=new Map(events.map(e=>[e.provider_message_id,e]));const out=jobs.map(j=>({id:j.id,job:j.status,delivery:latest.get(String(j.provider_sid||'').replace('telnyx:',''))?.status||'pending',error:j.last_error}));await fs.writeFile(dir+'/resumed-six-status.json',JSON.stringify({at:new Date().toISOString(),rows:out},null,2));console.log(JSON.stringify(out));
